    Raffle storage raffle = _raffles[raffleId];
-   if (raffle.status == RaffleStatus.PRIZE_LOCKED) return;
+   if (raffle.status == RaffleStatus.PRIZE_LOCKED && _checkRole(msg.sender, 0)) return;
