	uint256 currentLinkBalance = linkToken.balanceOf(address(this));

	if (fee > currentLinkBalance) {
		revert InsufficientLinkBalance(currentLinkBalance, fee);
	}

	messageId = router.ccipSend(ccipDestChainSelector, message);
